alter table fo_arconfigurazione add msg_invio_pec varchar2(4000 char);
ALTER TABLE DOMANDESTC add id_nodo varchar2(10 char);
alter table AMMINISTRAZIONI add STC_IDNODO varchar2(10 CHAR);
COMMENT ON COLUMN AMMINISTRAZIONI.STC_IDNODO is 'Id del nodo NLA registrato su STC';
alter table istanzehummingbird modify id_pratica varchar2(50 byte) null;
alter table istanzehummingbird modify docnum NUMBER(6,0) NULL;
alter table PERMISTANZE modify TABELLA  NUMBER(6,0) null;
ALTER TABLE ISTANZE ADD (CODICEPRATICATEL VARCHAR2(40) NULL);
ALTER TABLE CONFIGURAZIONE ADD (CODICE_ACCREDITAMENTO VARCHAR2(30 CHAR) );
CREATE OR REPLACE FORCE VIEW VW_LISTAPRATICHE AS SELECT istanze.codicecomune ,   istanze.idcomune ,   istanze.software  AS software ,   software.descrizionelunga   AS descsoftware ,   istanze.codiceistanza  AS idpratica ,   istanze.numeroistanza  AS numeropratica ,   TO_CHAR(istanze.data,'DD/MM/YYYY') AS datapresentazione ,   TO_CHAR(istanze.data,'YYYY')  AS annopresentazione ,   TO_CHAR(istanze.data,'MM')  AS mesepresentazione ,   istanze.numeroprotocollo ,   TO_CHAR(istanze.dataprotocollo,'DD/MM/YYYY') AS dataprotocollo ,   istanze.codiceinterventoproc  AS codiceintervento ,  
 vw_alberoproc.sc_descrizione  AS descrizioneintervento,   tipiprocedure.codiceprocedura ,   tipiprocedure.procedura ,   istanze.lavori AS oggetto ,   UPPER(istanze.lavori) AS oggettou ,   istanze.chiusura AS codstatopratica ,   stato  AS statopratica ,   responsabili.responsabile ,   responsabili.telefonolavoro  AS responsabile_telefono ,   NVL(stradario.codviario,stradario.codicestradario) AS pr_codviario ,   stradario.prefisso   || ' '   || stradario.descrizione AS pr_indirizzo ,   istanzestradario.CODICECIVICO AS pr_codcivico ,   istanze.civico AS pr_civico ,   istanze.codicearea  AS codicezonizzazione,   aree.denominazione  AS zonizzazione ,   anagrafe.codiceanagrafe  AS CodiceRichiedente ,  
 NVL(anagrafe.codicefiscale, '') AS codicefiscale ,   NVL(anagrafe.partitaiva, '')  AS partitaiva ,   anagrafe.nominativo   || ' '   || anagrafe.nome AS nominativo,   anagrafe.indirizzo ,   anagrafe.cap ,   anagrafe.citta  AS localita ,   comuneresidenza.comune AS citta ,   comuneresidenza.provincia , tipisoggetto.tiposoggetto AS tiporapporto , catasto.descrizione  AS tipocatasto , istanzemappali.foglio , istanzemappali.particella , istanzemappali.sub , tecnico.codiceanagrafe AS tec_codice ,  
 tecnico.nominativo || ' ' || tecnico.nome AS tec_nominativo , NVL(tecnico.codicefiscale, '') AS tec_codicefiscale, NVL(tecnico.partitaiva, '')  AS tec_partitaiva , azienda.codiceanagrafe  AS az_codice , azienda.nominativo || ' ' || azienda.nome AS az_nominativo , NVL(azienda.codicefiscale, '') AS az_codicefiscale, NVL(azienda.partitaiva, '')  AS az_partitaiva, istruttori.responsabile AS istruttore, istruttori.telefonolavoro AS istruttore_telefono, operatori.responsabile  AS operatore, operatori.telefonolavoro  AS operatore_telefono FROM istanze , software , anagrafe , istanzestradario , stradario , istanzemappali , vw_alberoproc , 
 responsabili , comuni comuneresidenza , tipisoggetto , statiistanza , anagrafe tecnico , anagrafe azienda , aree , catasto , tipiprocedure , responsabili istruttori, responsabili operatori WHERE software.codice  = istanze.software AND anagrafe.idcomune  = istanze.idcomune AND anagrafe.codiceanagrafe = istanze.codicerichiedente AND tecnico.idcomune(+) =istanze.idcomune AND tecnico.codiceanagrafe(+)  =istanze.codiceprofessionista AND azienda.idcomune(+) =istanze.idcomune AND azienda.codiceanagrafe(+)  =istanze.codicetitolarelegale AND statiistanza.idcomune = istanze.idcomune AND statiistanza.software = istanze.software AND statiistanza.codicestato = istanze.chiusura  
 AND istanzestradario.idcomune(+)  = istanze.idcomune AND istanzestradario.codiceistanza(+)  = istanze.codiceistanza AND istanzestradario.primario(+)  = 1 AND stradario.idcomune = istanzestradario.idcomune AND stradario.codicestradario  = istanzestradario.codicestradario AND istanzemappali.idcomune(+) =istanze.idcomune AND istanzemappali.fkcodiceistanza(+) =istanze.codiceistanza AND istanzemappali.primario(+) = 1 AND vw_alberoproc.idcomune  = istanze.idcomune AND vw_alberoproc.sc_id = istanze.codiceinterventoproc AND responsabili.idcomune(+) =istanze.idcomune AND responsabili.codiceresponsabile(+)=istanze.codiceresponsabileproc AND comuneresidenza.codicecomune(+) =anagrafe.comuneresidenza AND tipisoggetto.idcomune(+) =istanze.idcomune AND 
 tipisoggetto.codicetiposoggetto(+)=istanze.fkcodicesoggetto AND aree.idcomune(+) =istanze.idcomune AND aree.codicearea(+) =istanze.codicearea AND catasto.codice(+)  =istanzemappali.codicecatasto AND tipiprocedure.idcomune(+)  =istanze.idcomune AND tipiprocedure.codiceprocedura(+)  =istanze.codiceprocedura AND istruttori.idcomune(+)  =istanze.idcomune AND istruttori.codiceresponsabile(+)  =istanze.codiceistruttore AND operatori.idcomune(+) =istanze.idcomune AND operatori.codiceresponsabile(+) =istanze.codiceresponsabile;